import React from 'react';
import type { MedicalIncidentReport, IncidentReportSummaryItem } from '../../../models/MedicalIncident';
import { fmtDate } from './monthlyReportEditorShared';
import s from './MonthlyReportEditor.module.css';

interface Props {
  report: MedicalIncidentReport;
  effectiveDateFrom: string;
  effectiveDateTo: string;
  voluntaryCount: number;
  mandatoryCount: number;
  departments: { key: string; label: string; count: number }[];
  clinicalCount: number;
  serviceCount: number;
  fallCount: number;
  summaryItems: IncidentReportSummaryItem[];
  summaryLoading: boolean;
}

export const MonthlyReportSectionSummary: React.FC<Props> = ({
  report,
  effectiveDateFrom,
  effectiveDateTo,
  voluntaryCount,
  mandatoryCount,
  departments,
  clinicalCount,
  serviceCount,
  fallCount,
  summaryItems,
  summaryLoading,
}) => (
  <div className={s.summarySection}>
    <div className={s.summaryCard}>
      <div className={s.summaryCardTitle}>
        <i className="fas fa-calendar-alt" style={{ color: '#0066cc' }} />
        1.1 Thời gian báo cáo
      </div>
      <div className={s.summaryRow}>
        <span className={s.summaryRowLabel}>Từ ngày:</span>
        <strong>{fmtDate(effectiveDateFrom) || '—'}</strong>
      </div>
      <div className={s.summaryRow}>
        <span className={s.summaryRowLabel}>Đến ngày:</span>
        <strong>{fmtDate(effectiveDateTo) || '—'}</strong>
      </div>
    </div>

    <div className={s.summaryCard}>
      <div className={s.summaryCardTitle}>
        <i className="fas fa-file-medical-alt" style={{ color: '#059669' }} />
        1.2 Số lượng báo cáo
      </div>
      <div className={s.summaryTotalRow}>
        Tổng: <strong className={s.summaryTotalNum}>{report.totalCount}</strong> sự cố / sai sót chuyên môn
      </div>
      <div className={s.summaryIndent}>
        <div className={s.summaryIndentRow}>
          <span className={s.summaryIndentBullet}>+</span>
          <span>Báo cáo tự nguyện:</span>
          <strong>{voluntaryCount}</strong> sự cố
        </div>
        <div className={s.summaryIndentRow}>
          <span className={s.summaryIndentBullet}>+</span>
          <span>Báo cáo bắt buộc:</span>
          <strong>{mandatoryCount}</strong> sự cố
        </div>
      </div>
    </div>

    <div className={s.summaryCard}>
      <div className={s.summaryCardTitle}>
        <i className="fas fa-hospital" style={{ color: '#7c3aed' }} />
        Khoa báo cáo ({departments.length} khoa)
      </div>
      {departments.length === 0 ? (
        <div className={s.summaryEmpty}>Chưa có dữ liệu khoa báo cáo</div>
      ) : (
        <div className={s.summaryDeptList}>
          {departments.map((d) => (
            <div key={d.key} className={s.summaryDeptRow}>
              <span className={s.summaryDeptName}>+ {d.label}</span>
              <span className={s.summaryDeptCount}>{d.count} sự cố</span>
            </div>
          ))}
        </div>
      )}
    </div>

    <div className={s.summaryCard}>
      <div className={s.summaryCardTitle}>
        <i className="fas fa-layer-group" style={{ color: '#d97706' }} />
        Tổng hợp báo cáo sự cố
      </div>
      <div className={s.summaryIndent}>
        <div className={s.summaryIndentRow}>
          <span className={s.summaryIndentBullet}>+</span>
          <span>Sự cố liên quan quy trình chuyên môn:</span>
          <strong>{clinicalCount}</strong> sự cố
        </div>
        <div className={s.summaryIndentRow}>
          <span className={s.summaryIndentBullet}>+</span>
          <span>Sự cố liên quan cung cấp nhóm dịch vụ:</span>
          <strong>{serviceCount}</strong> sự cố
        </div>
        <div className={s.summaryIndentRow}>
          <span className={s.summaryIndentBullet}>+</span>
          <span>Sự cố té ngã:</span>
          <strong>{fallCount}</strong> sự cố
        </div>
      </div>
    </div>

    <div className={s.summaryCard}>
      <div className={s.summaryCardTitle}>
        <i className="fas fa-table" style={{ color: '#475569' }} />
        Chi tiết sự cố theo từng khoa
        {summaryLoading && (
          <span className={s.summaryPhaseNote}>
            <i className="fas fa-spinner fa-spin" style={{ marginRight: 4 }} />Đang tải...
          </span>
        )}
        {!summaryLoading && summaryItems.length > 0 && (
          <span className={s.summaryPhaseNote}>({summaryItems.length} sự cố)</span>
        )}
      </div>
      <div className={s.summaryTableWrapper}>
        <table className={s.summaryTable}>
          <thead>
            <tr>
              <th style={{ width: '20%' }}>Khoa báo cáo</th>
              <th style={{ width: '42%' }}>Sự cố/ sai sót/ nguy cơ</th>
              <th style={{ width: '38%' }}>Nguyên nhân</th>
            </tr>
          </thead>
          <tbody>
            {summaryItems.length > 0
              ? summaryItems.map((item, idx) => (
                  <tr key={idx}>
                    <td className={s.summaryTableGroupCell}>{item.departmentName || '—'}</td>
                    <td>{item.briefDescription || '—'}</td>
                    <td style={{ fontStyle: item.causeDescription ? 'normal' : 'italic', color: item.causeDescription ? 'inherit' : '#94a3b8' }}>
                      {item.causeDescription || '(chưa có phân tích nguyên nhân)'}
                    </td>
                  </tr>
                ))
              : (
                <tr>
                  <td colSpan={3} style={{ textAlign: 'center', fontStyle: 'italic', color: '#94a3b8', padding: '16px 8px' }}>
                    {summaryLoading
                      ? 'Đang tải dữ liệu...'
                      : (!effectiveDateFrom || !effectiveDateTo)
                        ? 'Chọn kỳ báo cáo để xem chi tiết sự cố'
                        : 'Không có sự cố trong kỳ này'}
                  </td>
                </tr>
              )}
          </tbody>
        </table>
      </div>
    </div>
  </div>
);
