import React from 'react';
import type { RpnRow } from './PrintableRecommendationDoc';
import { getRpnColor } from './monthlyReportEditorShared';
import s from './MonthlyReportEditor.module.css';

interface Props {
  readOnly: boolean;
  rpnRows: RpnRow[];
  updateRpn: (idx: number, field: keyof RpnRow, value: string) => void;
  addRpnRow: () => void;
  removeRpnRow: (idx: number) => void;
}

export const MonthlyReportSectionRpn: React.FC<Props> = ({
  readOnly,
  rpnRows,
  updateRpn,
  addRpnRow,
  removeRpnRow,
}) => (
  <div className={s.rpnSection}>
    <div className={s.rpnHeader}>
      <div className={s.rpnDescription}>
        <i className="fas fa-info-circle" style={{ color: '#3b82f6', marginRight: 6 }} />
        Nhập tên sự cố và điểm <strong>S × O × D</strong> (thang 1–10) để tính chỉ số RPN.
        Sau đó sang <strong>Mục 4</strong> để điền nguyên nhân và đề xuất.
      </div>
      {!readOnly && (
        <button type="button" className={s.btnAddRow} onClick={addRpnRow}>
          <i className="fas fa-plus" /> Thêm sự cố
        </button>
      )}
    </div>

    <div className={s.rpnCards}>
      {rpnRows.map((row, idx) => {
        const rpn =
          row.s !== '' && row.o !== '' && row.d !== ''
            ? Number(row.s) * Number(row.o) * Number(row.d)
            : null;
        const rpnColor = getRpnColor(rpn);

        return (
          <div key={idx} className={s.rpnCard}>
            <div className={s.rpnCardHeader}>
              <span className={s.rpnCardIndex}>{idx + 1}</span>
              <input
                className={s.rpnNameInput}
                type="text"
                readOnly={readOnly}
                placeholder="Tên sự cố y khoa..."
                value={row.incidentName}
                onChange={(e) => updateRpn(idx, 'incidentName', e.target.value)}
              />
              {rpn !== null && (
                <span className={s.rpnBadge} style={{ background: rpnColor }}>
                  RPN {rpn}
                </span>
              )}
              {!readOnly && (
                <button
                  type="button"
                  className={s.rpnRemoveBtn}
                  onClick={() => removeRpnRow(idx)}
                  title="Xoá"
                >
                  <i className="fas fa-times" />
                </button>
              )}
            </div>

            <div className={s.rpnCardScores}>
              {(['s', 'o', 'd'] as const).map((field) => (
                <label key={field} className={s.rpnScoreLabel}>
                  <span className={s.rpnScoreKey}>{field.toUpperCase()}</span>
                  <input
                    className={s.rpnNumInput}
                    type="number"
                    min={1}
                    max={10}
                    readOnly={readOnly}
                    placeholder="1-10"
                    value={row[field]}
                    onChange={(e) => updateRpn(idx, field, e.target.value)}
                  />
                </label>
              ))}
              <span className={s.rpnResult} style={{ color: rpnColor || '#94a3b8' }}>
                = {rpn !== null ? <strong>{rpn}</strong> : '—'}
              </span>
              <span className={s.rpnScoreHint}>
                S = Mức độ nghiêm trọng · O = Xác suất xảy ra · D = Khả năng phát hiện
              </span>
            </div>
          </div>
        );
      })}
    </div>

    <div className={s.rpnLegend}>
      <span style={{ color: '#dc2626' }}>■ ≥ 200: Ưu tiên cao</span>
      <span style={{ color: '#f59e0b' }}>■ 100–199: Cần theo dõi</span>
      <span style={{ color: '#10b981' }}>■ &lt; 100: Thấp</span>
    </div>
  </div>
);
