import type { MonthlyIncidentReportDraft, MedicalIncidentReportFilters, MedicalIncidentReport } from '../../../models/MedicalIncident';
import type { RpnRow } from './PrintableRecommendationDoc';

export type ChartDisplayType = 'doughnut' | 'bar-v' | 'bar-h';
export type MonthlyReportSectionTab = 'summary' | 'analysis' | 'rpn' | 'solution';

export const PAGE_STYLE = `
  /* WYSIWYG: lề NĐ 30/2020 nằm trên .document padding — @page margin = 0
   * để preview (screen) và print cùng một box model. */
  @page {
    size: A4 portrait;
    margin: 0;
    background: white;
  }
  @media print {
    html, body {
      margin: 0 !important;
      padding: 0 !important;
      overflow: visible !important;
      height: auto !important;
      width: 100% !important;
      background: white !important;
    }
    body > div {
      zoom: 1 !important;
      transform: none !important;
      background: white !important;
    }
  }
`;

export const EMPTY_RPN_ROW = (): RpnRow => ({
  incidentName: '',
  causeDetail:  '',
  s: '',
  o: '',
  d: '',
  solution:     '',
});

export function mapDraftRpnRows(rows: MonthlyIncidentReportDraft['rpnRows']): RpnRow[] {
  if (!rows?.length) return [EMPTY_RPN_ROW()];
  return rows.map((r) => ({
    incidentName: r.incidentName ?? '',
    causeDetail:  r.causeDetail  ?? '',
    s: r.s ?? '',
    o: r.o ?? '',
    d: r.d ?? '',
    solution: r.solution ?? '',
  }));
}

export const isNativeMobile = () =>
  typeof navigator !== 'undefined' &&
  /android|iphone|ipad|ipod/i.test(navigator.userAgent);

export function fmtDate(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}

export function pct(count: number, total: number) {
  if (!total) return '0';
  return ((count / total) * 100).toFixed(1);
}

export function getRpnColor(rpn: number | null) {
  if (rpn === null) return '';
  return rpn >= 200 ? '#dc2626' : rpn >= 100 ? '#f59e0b' : '#10b981';
}

export function getPeriodLabel(filters: MedicalIncidentReportFilters): string {
  if (filters.dateFrom && filters.dateTo) {
    const from = new Date(filters.dateFrom);
    const to   = new Date(filters.dateTo);
    if (from.getFullYear() === to.getFullYear() && from.getMonth() === to.getMonth())
      return `Tháng ${from.getMonth() + 1}/${from.getFullYear()}`;
    return `${from.toLocaleDateString('vi-VN')} – ${to.toLocaleDateString('vi-VN')}`;
  }
  if (filters.year) return `Năm ${filters.year}`;
  return 'Kỳ báo cáo';
}

/** Type-group keys counted as «cung cấp nhóm dịch vụ» (excl. clinical group1 + fall group7). */
const SERVICE_TYPE_GROUP_KEYS = new Set([
  'group2', 'group3', 'group4', 'group5', 'group6',
  'group8', 'group9', 'group10', 'group11',
]);

/**
 * Mục 1.2–1.3 stats shared by editor + print.
 * SSOT: do NOT use residual `totalCount - clinical - fall - infra` — type groups are multi-select
 * so residual can go negative or undercount service buckets (GAP-SCYK-METRIC-07).
 */
export function deriveMonthlySection1Stats(report: MedicalIncidentReport) {
  const groupCount = (key: string) =>
    report.byIncidentTypeGroup.find((x) => x.key === key)?.count ?? 0;

  const voluntaryCount = report.byReportType.find((x) => x.key === 'voluntary')?.count ?? 0;
  const mandatoryCount = report.byReportType.find((x) => x.key === 'mandatory')?.count ?? 0;
  /** SSOT: mọi báo cáo đếm theo Khoa báo cáo (`byReportingDepartment`). */
  const reportingDepartments = report.byReportingDepartment.filter((d) => d.count > 0);
  const clinicalCount = groupCount('group1');
  const fallCount = groupCount('group7');
  const serviceCount = report.byIncidentTypeGroup
    .filter((x) => SERVICE_TYPE_GROUP_KEYS.has(x.key))
    .reduce((sum, x) => sum + x.count, 0);

  return {
    voluntaryCount,
    mandatoryCount,
    reportingDepartments,
    clinicalCount,
    serviceCount,
    fallCount,
  };
}
